    story_tent3: {
      de: ['T:DU HAST DIE FEDER! SCHÖN FÜR DICH. ICH HABE IMMER NOCH KEINE BEINE.', 'T:HÖR ZU. MEIN NEFFE WILL DIE WELT SEHEN. BEVOR WIR SIE EROBERN. NIMM IHN MIT.', 'H:... ER SIEHT AUS WIE DU. NUR KLEINER.', 'T:KOMPAKTER. ER HAUT ZU, WENN WAS KOMMT. UND ER REDET. VIEL. VIEL ZU VIEL.'],
      en: ['T:YOU GOT THE FEATHER! GOOD FOR YOU. I STILL HAVE NO LEGS.', 'T:LISTEN. MY NEPHEW WANTS TO SEE THE WORLD. BEFORE WE CONQUER IT. TAKE HIM WITH YOU.', 'H:... HE LOOKS LIKE YOU. ONLY SMALLER.', 'T:MORE COMPACT. HE SLAPS ANYTHING THAT COMES CLOSE. AND HE TALKS. A LOT. FAR TOO MUCH.'],
      fr: ["T:TU AS LA PLUME ! TANT MIEUX POUR TOI. MOI, JE N'AI TOUJOURS PAS DE JAMBES.", "T:ÉCOUTE. MON NEVEU VEUT VOIR LE MONDE. AVANT QU'ON LE CONQUIÈRE. EMMÈNE-LE.", 'H:... IL TE RESSEMBLE. EN PLUS PETIT.', 'T:EN PLUS COMPACT. IL FRAPPE CE QUI APPROCHE. ET IL PARLE. BEAUCOUP. BEAUCOUP TROP.'],
      es: ['T:¡TIENES LA PLUMA! ME ALEGRO POR TI. YO SIGO SIN PIERNAS.', 'T:ESCUCHA. MI SOBRINO QUIERE VER EL MUNDO. ANTES DE QUE LO CONQUISTEMOS. LLÉVATELO.', 'H:... SE PARECE A TI. PERO MÁS PEQUEÑO.', 'T:MÁS COMPACTO. GOLPEA LO QUE SE ACERCA. Y HABLA. MUCHO. DEMASIADO.'],
      ja: ['T:羽を手に入れたか！よかったな。オレ様はまだ足がない。', 'T:いいか。オレ様の甥が世界を見たいそうだ。征服する前にな。連れていけ。', 'H:……お前にそっくりだな。小さいだけで。', 'T:コンパクトなんだ。近づく奴はひっぱたく。それによくしゃべる。しゃべりすぎる。'],
      zh: ['T:你拿到羽毛了！恭喜。我还是没有腿。', 'T:听着。我侄子想看看世界。在我们征服它之前。带上他。', 'H:……他长得跟你一样。只是小一点。', 'T:是紧凑一点。谁靠近他就抽谁。而且他话很多。多得要命。'],
    },
    story_tent3Again: { de: 'PASS AUF MEINEN NEFFEN AUF. UND ER AUF DICH. DAS IST DER DEAL.', en: "LOOK AFTER MY NEPHEW. AND HE'LL LOOK AFTER YOU. THAT'S THE DEAL.", fr: "VEILLE SUR MON NEVEU. ET LUI SUR TOI. C'EST LE MARCHÉ.", es: 'CUIDA DE MI SOBRINO. Y ÉL CUIDARÁ DE TI. ESE ES EL TRATO.', ja: '甥を頼んだぞ。甥もお前を守る。そういう取引だ。', zh: '照顾好我侄子。他也会照顾你。这就是交易。' },
