    itemD_chicken: { de: 'MEHR BEUTE UND GOLD. QUIETSCHT.', en: 'MORE LOOT AND GOLD. SQUEAKS.', fr: "PLUS DE BUTIN ET D'OR. COUINE.", es: 'MÁS BOTÍN Y ORO. CHIRRÍA.', ja: '戦利品とゴールド増加。キュッと鳴る。', zh: '更多战利品和金币。会吱吱叫。' },
    story_wings: {
      de: ['A:DIE SEELE DER FLEDERMAUS! ↓ ↑ UND SPRUNG - UND DU FLATTERST. SPRUNG ODER ANGRIFF, UND DU BIST WIEDER DU.', 'A:GANZ OBEN IN DIESER HALLE, UNTER DER DECKE, IST EIN SIMS. NIEMAND WAR JE DA OBEN. NICHT MAL DIE SPINNEN.', 'H:UND WAS IST DA OBEN?', 'A:DER DACHBODEN. DER GRAF BEWAHRT DORT DINGE AUF, DIE ER NICHT MEHR BRAUCHT. ODER NICHT VERSTEHT.'],
      en: ["A:THE BAT'S SOUL! ↓ ↑ AND JUMP - AND YOU FLAP. JUMP OR ATTACK, AND YOU'RE YOU AGAIN.", "A:AT THE VERY TOP OF THIS HALL, UNDER THE CEILING, THERE'S A LEDGE. NOBODY HAS EVER BEEN UP THERE. NOT EVEN THE SPIDERS.", "H:AND WHAT'S UP THERE?", "A:THE ATTIC. THE COUNT KEEPS THINGS THERE HE NO LONGER NEEDS. OR DOESN'T UNDERSTAND."],
      fr: ["A:L'ÂME DE LA CHAUVE-SOURIS ! ↓ ↑ ET SAUT - ET TU BATS DES AILES. SAUT OU ATTAQUE, ET TU REDEVIENS TOI.", "A:TOUT EN HAUT DE CE HALL, SOUS LE PLAFOND, IL Y A UNE CORNICHE. PERSONNE N'Y EST JAMAIS MONTÉ. MÊME PAS LES ARAIGNÉES.", "H:ET QU'Y A-T-IL LÀ-HAUT ?", "A:LE GRENIER. LE COMTE Y RANGE CE DONT IL N'A PLUS BESOIN. OU CE QU'IL NE COMPREND PAS."],
      es: ['A:¡EL ALMA DEL MURCIÉLAGO! ↓ ↑ Y SALTO, Y ALETEAS. SALTO O ATAQUE, Y VUELVES A SER TÚ.', 'A:EN LO MÁS ALTO DE ESTE VESTÍBULO, BAJO EL TECHO, HAY UNA CORNISA. NADIE HA SUBIDO NUNCA. NI LAS ARAÑAS.', 'H:¿Y QUÉ HAY AHÍ ARRIBA?', 'A:EL DESVÁN. EL CONDE GUARDA ALLÍ LO QUE YA NO NECESITA. O LO QUE NO ENTIENDE.'],
      ja: ['A:コウモリの魂か！↓↑とジャンプで羽ばたける。ジャンプか攻撃で元に戻る。', 'A:このホールのいちばん上、天井の下に張り出しがある。誰も行ったことがない。クモでさえな。', 'H:そこには何がある？', 'A:屋根裏だ。伯爵がもう要らない物を置いている。あるいは理解できない物を。'],
      zh: ['A:蝙蝠之魂！↓↑加跳跃，你就能扑腾起来。跳跃或攻击，就变回你自己。', 'A:这座门厅最高处，天花板下面有个檐台。从来没人上去过。连蜘蛛都没有。', 'H:上面有什么？', 'A:阁楼。伯爵把不再需要的东西放在那里。或者是他看不懂的东西。'],
    },
    story_wingsAgain: { de: 'DER SIMS UNTER DER DECKE - FLIEG HOCH. ↓ ↑ UND SPRUNG.', en: 'THE LEDGE UNDER THE CEILING - FLY UP. ↓ ↑ AND JUMP.', fr: 'LA CORNICHE SOUS LE PLAFOND - VOLE. ↓ ↑ ET SAUT.', es: 'LA CORNISA BAJO EL TECHO: VUELA. ↓ ↑ Y SALTO.', ja: '天井の下の張り出しへ飛べ。↓↑とジャンプだ。', zh: '天花板下的檐台——飞上去。↓↑加跳跃。' },
    // Schloss-Modus: Ende (Epilog, Ergebnis, Neues Spiel+)
    story_epilogue: {
      de: ['A:{1}! DU HAST ES GESCHAFFT! DER GRAF IST ... NUN JA. WIEDER STAUB. BIS ZUM NÄCHSTEN JAHRHUNDERT.', 'A:UND DER FLUCH IST WEG. ICH KANN WIEDER HÜPFEN. GUCK! ... GUT, ICH ÜBE NOCH.', 'L:ICH HABE ALLES IN DIE CHRONIK EINGETRAGEN. KAPITEL 1691: „JEMAND HAT ENDLICH AUFGERÄUMT.“', 'L:DIE BIBLIOTHEK BLEIBT OFFEN. FALLS DU JE EINE TOILETTE FINDEST - SAG BESCHEID.', 'T:HE! WARTE! JETZT, WO DER GRAF WEG IST ... IST DIE STELLE FREI?', 'T:WELTHERRSCHAFT, SCHRITT 2: EIN SCHLOSS. ERLEDIGT. SCHRITT 1 (BEINE) IST ... IN ARBEIT.', 'H:WIR SEHEN UNS IN HUNDERT JAHREN.', 'A:ICH BRINGE KUCHEN MIT.'],
      en: ['A:{1}! YOU DID IT! THE COUNT IS ... WELL. DUST AGAIN. UNTIL NEXT CENTURY.', "A:AND THE CURSE IS GONE. I CAN HOP AGAIN. LOOK! ... OKAY, I'M STILL PRACTISING.", 'L:I HAVE WRITTEN IT ALL INTO THE CHRONICLE. CHAPTER 1691: "SOMEONE FINALLY TIDIED UP."', 'L:THE LIBRARY STAYS OPEN. IF YOU EVER FIND A TOILET - LET ME KNOW.', 'T:HEY! WAIT! NOW THAT THE COUNT IS GONE ... IS THE POSITION OPEN?', 'T:WORLD DOMINATION, STEP 2: A CASTLE. DONE. STEP 1 (LEGS) IS ... IN PROGRESS.', 'H:SEE YOU IN A HUNDRED YEARS.', "A:I'LL BRING CAKE."],
      fr: ["A:{1} ! TU AS RÉUSSI ! LE COMTE EST ... BON. DE NOUVEAU POUSSIÈRE. JUSQU'AU SIÈCLE PROCHAIN.", "A:ET LA MALÉDICTION A DISPARU. JE SAIS DE NOUVEAU SAUTILLER. REGARDE ! ... BON, JE M'ENTRAÎNE ENCORE.", "L:J'AI TOUT NOTÉ DANS LA CHRONIQUE. CHAPITRE 1691 : « QUELQU'UN A ENFIN RANGÉ. »", 'L:LA BIBLIOTHÈQUE RESTE OUVERTE. SI TU TROUVES UN JOUR DES TOILETTES - PRÉVIENS-MOI.', 'T:HÉ ! ATTENDS ! MAINTENANT QUE LE COMTE EST PARTI ... LE POSTE EST LIBRE ?', 'T:DOMINATION MONDIALE, ÉTAPE 2 : UN CHÂTEAU. FAIT. ÉTAPE 1 (LES JAMBES) EST ... EN COURS.', 'H:À DANS CENT ANS.', "A:J'APPORTERAI DU GÂTEAU."],
      es: ['A:¡{1}! ¡LO LOGRASTE! EL CONDE ES ... BUENO. POLVO OTRA VEZ. HASTA EL PRÓXIMO SIGLO.', 'A:Y LA MALDICIÓN SE FUE. YA PUEDO DAR SALTITOS. ¡MIRA! ... VALE, AÚN PRACTICO.', 'L:LO HE ANOTADO TODO EN LA CRÓNICA. CAPÍTULO 1691: «POR FIN ALGUIEN ORDENÓ».', 'L:LA BIBLIOTECA SIGUE ABIERTA. SI ALGUNA VEZ ENCUENTRAS UN BAÑO, AVÍSAME.', 'T:¡EH! ¡ESPERA! AHORA QUE EL CONDE NO ESTÁ ... ¿EL PUESTO ESTÁ LIBRE?', 'T:DOMINACIÓN MUNDIAL, PASO 2: UN CASTILLO. HECHO. PASO 1 (PIERNAS) ESTÁ ... EN PROCESO.', 'H:NOS VEMOS EN CIEN AÑOS.', 'A:YO TRAIGO EL PASTEL.'],
      ja: ['A:{1}！やったな！伯爵は……まあ、また塵だ。次の世紀まで。', 'A:呪いも解けた。また小さくジャンプできる。見ろ！……うん、まだ練習中だ。', 'L:すべて年代記に書き記した。1691年の章：「ついに誰かが片付けた」。', 'L:書庫は開けておく。もしトイレを見つけたら、教えておくれ。', 'T:おい！待て！伯爵がいなくなった今……その席、空いてる？', 'T:世界征服、第二段階：城。完了。第一段階（足）は……進行中だ。', 'H:また百年後に会おう。', 'A:ケーキを持ってくるよ。'],
      zh: ['A:{1}！你做到了！伯爵……嗯，又变成灰了。下个世纪见。', 'A:诅咒也解除了。我又能蹦了。你看！……好吧，我还在练。', 'L:我已经全写进编年史了。1691年章：“终于有人打扫干净了。”', 'L:书库会一直开着。要是你找到了厕所——告诉我一声。', 'T:嘿！等等！伯爵走了……这个位置空出来了吗？', 'T:征服世界第二步：一座城堡。完成。第一步（腿）……进行中。', 'H:一百年后见。', 'A:我会带蛋糕来。'],
    },
