    story_pris1Again: { de: 'ICH HABE TEE. FÜR NEBEL. DURCH DAS GITTER.', en: 'I HAVE TEA. FOR MIST. THROUGH THE BARS.', fr: "J'AI DU THÉ. POUR LA BRUME. À TRAVERS LES BARREAUX.", es: 'TENGO TÉ. PARA LA NIEBLA. A TRAVÉS DE LOS BARROTES.', ja: 'お茶がある。霧のために。鉄格子越しに。', zh: '我有茶。给雾喝的。隔着铁栏。' },
    story_pris2Again: { de: 'ICH BLEIBE NOCH. DIE MIETE IST GÜNSTIG. NULL.', en: "I'LL STAY A BIT LONGER. THE RENT IS CHEAP. ZERO.", fr: 'JE RESTE ENCORE UN PEU. LE LOYER EST BAS. ZÉRO.', es: 'ME QUEDO UN RATO MÁS. EL ALQUILER ES BARATO. CERO.', ja: 'もう少しここにいる。家賃が安いんだ。タダだ。', zh: '我再待一阵。房租便宜。免费。' },
    story_fogAgain: { de: 'DER KERKER - TÜR MITTEN IM KOLOSSEUM. ALS NEBEL DURCHS GITTER.', en: 'THE DUNGEON - DOOR IN THE MIDDLE OF THE COLOSSEUM. THROUGH THE BARS AS MIST.', fr: 'LE CACHOT - PORTE AU MILIEU DU COLISÉE. À TRAVERS LES BARREAUX EN BRUME.', es: 'LA MAZMORRA: PUERTA EN MEDIO DEL COLISEO. COMO NIEBLA, POR LOS BARROTES.', ja: '地下牢はコロシアムの真ん中の扉だ。霧になって鉄格子を抜けろ。', zh: '地牢——斗技场中间的门。变成雾穿过铁栏。' },
    story_pris1: {
      de: ['P:PSST! DU DA! HAST DU EINEN SCHLÜSSEL? ... NEIN? EGAL. ICH HABE EINEN GANZEN BUND. PASST NUR NIRGENDS.', 'P:ICH SITZE HIER SEIT 1391. WEGEN FALSCHPARKENS. MIT EINER KUTSCHE.', 'H:DAS SIND ÜBER DREIHUNDERT JAHRE.', 'P:DIE ZEIT VERGEHT, WENN MAN SICH AMÜSIERT. HIER AMÜSIERT SICH KEINER. SIE VERGEHT TROTZDEM.', 'P:WENN DU JE ZU NEBEL WIRST, KOMM REIN. ICH HABE TEE. ER IST ... GUT ABGELAGERT.'],
      en: ['P:PSST! YOU THERE! GOT A KEY? ... NO? NEVER MIND. I HAVE A WHOLE RING OF THEM. NONE OF THEM FIT.', "P:I'VE BEEN IN HERE SINCE 1391. FOR ILLEGAL PARKING. WITH A CARRIAGE.", "H:THAT'S OVER THREE HUNDRED YEARS.", "P:TIME FLIES WHEN YOU'RE HAVING FUN. NOBODY HAS FUN IN HERE. IT FLIES ANYWAY.", "P:IF YOU EVER TURN INTO MIST, COME IN. I HAVE TEA. IT'S ... WELL AGED."],
      fr: ["P:PSST ! TOI ! TU AS UNE CLÉ ? ... NON ? TANT PIS. J'EN AI TOUT UN TROUSSEAU. AUCUNE NE MARCHE.", 'P:JE SUIS ICI DEPUIS 1391. POUR STATIONNEMENT INTERDIT. AVEC UN CARROSSE.', 'H:ÇA FAIT PLUS DE TROIS CENTS ANS.', "P:LE TEMPS PASSE VITE QUAND ON S'AMUSE. ICI, PERSONNE NE S'AMUSE. IL PASSE QUAND MÊME.", "P:SI TU DEVIENS UN JOUR BRUME, ENTRE. J'AI DU THÉ. IL EST ... BIEN VIEILLI."],
      es: ['P:¡PSST! ¡TÚ! ¿TIENES UNA LLAVE? ... ¿NO? DA IGUAL. TENGO UN LLAVERO ENTERO. NINGUNA ENCAJA.', 'P:ESTOY AQUÍ DESDE 1391. POR APARCAR MAL. UNA CARROZA.', 'H:ESO SON MÁS DE TRESCIENTOS AÑOS.', 'P:EL TIEMPO VUELA CUANDO TE DIVIERTES. AQUÍ NADIE SE DIVIERTE. VUELA IGUAL.', 'P:SI ALGUNA VEZ TE CONVIERTES EN NIEBLA, PASA. TENGO TÉ. ESTÁ ... BIEN AÑEJADO.'],
      ja: ['P:おい！そこの！鍵を持ってるか？……ない？まあいい。鍵束ならある。どれも合わないが。', 'P:1391年からここにいる。駐車違反でな。馬車の。', 'H:三百年以上じゃないか。', 'P:楽しい時間は早く過ぎる。ここに楽しみはない。それでも過ぎる。', 'P:もし霧になれたら寄っていけ。お茶がある。……よく熟成している。'],
      zh: ['P:嘘！你！有钥匙吗？……没有？算了。我有一整串钥匙。一把都对不上。', 'P:我从1391年就关在这里了。因为乱停车。停的是马车。', 'H:那都三百多年了。', 'P:快乐的时光过得快。这里没人快乐。可时间照样过。', 'P:要是你哪天变成雾，就进来坐坐。我有茶。……陈年的。'],
    },
    story_pris2: {
      de: ['P:DU BIST DURCH DIE GITTER GEKOMMEN?! ALS NEBEL?! ... KANNST DU MIR DAS BEIBRINGEN?', 'H:DAFÜR BRAUCHT MAN DIE ASCHE DES NEBELS, FÜRCHTE ICH.', 'P:SCHADE. HIER, NIMM MEINEN SCHLÜSSELBUND. PASST NIRGENDS, ABER ER FÜHLT SICH WICHTIG AN.', 'P:UND TRINK DEN TEE. NEIN. LIEBER NICHT.', 'P:ÜBRIGENS: MEINE UNTERTASSE IST WEG. SEIT 1391. OHNE UNTERTASSE IST TEE NUR EIN NASSES GERÜCHT.'],
      en: ['P:YOU CAME THROUGH THE BARS?! AS MIST?! ... CAN YOU TEACH ME THAT?', "H:I'M AFRAID YOU NEED THE ASH OF MIST.", 'P:PITY. HERE, TAKE MY RING OF KEYS. FITS NOTHING, BUT IT FEELS IMPORTANT.', 'P:AND DRINK THE TEA. NO. BETTER NOT.', 'P:BY THE WAY: MY SAUCER IS GONE. SINCE 1391. WITHOUT A SAUCER, TEA IS JUST A WET RUMOR.'],
      fr: ["P:TU ES PASSÉ À TRAVERS LES BARREAUX ?! EN BRUME ?! ... TU PEUX M'APPRENDRE ?", "H:IL FAUT LA CENDRE DE BRUME, J'EN AI PEUR.", "P:DOMMAGE. TIENS, PRENDS MON TROUSSEAU. IL N'OUVRE RIEN, MAIS IL A L'AIR IMPORTANT.", 'P:ET BOIS LE THÉ. NON. MIEUX VAUT PAS.', 'P:AU FAIT : MA SOUCOUPE A DISPARU. DEPUIS 1391. SANS SOUCOUPE, LE THÉ N\'EST QU\'UNE RUMEUR MOUILLÉE.'],
      es: ['P:¡¿HAS ATRAVESADO LOS BARROTES?! ¡¿COMO NIEBLA?! ... ¿ME LO ENSEÑAS?', 'H:ME TEMO QUE HACE FALTA LA CENIZA DE NIEBLA.', 'P:LÁSTIMA. TOMA, MI LLAVERO. NO ABRE NADA, PERO PARECE IMPORTANTE.', 'P:Y BÉBETE EL TÉ. NO. MEJOR NO.', 'P:POR CIERTO: MI PLATILLO HA DESAPARECIDO. DESDE 1391. SIN PLATILLO, EL TÉ ES SOLO UN RUMOR MOJADO.'],
      ja: ['P:鉄格子を抜けてきたのか？！霧になって？！……それ、教えてくれないか？', 'H:霧の灰が必要だと思う。', 'P:残念だ。ほら、鍵束をやろう。どこにも合わないが、大事そうな気がする。', 'P:それからお茶を飲め。いや、やめておけ。', 'P:ところで、わしの受け皿がない。1391年からだ。受け皿のない紅茶など、ただの濡れたうわさだ。'],
      zh: ['P:你穿过铁栏进来了？！变成雾？！……能教教我吗？', 'H:恐怕得有雾之灰才行。', 'P:可惜。给，拿着我的钥匙串。哪把锁都打不开，但感觉很重要。', 'P:再喝杯茶吧。不，还是别喝了。', 'P:对了：我的茶托不见了。从1391年起。没有茶托，茶只是个湿漉漉的传闻。'],
    },
    story_fog: {
      de: ['A:DIE ASCHE DES NEBELS! ↑ ↓ UND SPRUNG - UND DU BIST EIN GERÜCHT. NICHTS TRIFFT DICH, UND DU PASST DURCH JEDES GITTER.', 'A:IM KOLOSSEUM GIBT ES EINE TÜR ZUM KERKER. HINTER DEM GITTER SITZT JEMAND. SEIT 1391. ER HAT ANGEBLICH TEE.'],
      en: ["A:THE ASH OF MIST! ↑ ↓ AND JUMP - AND YOU'RE A RUMOR. NOTHING HITS YOU, AND YOU FIT THROUGH ANY BARS.", "A:THERE'S A DOOR TO THE DUNGEON IN THE COLOSSEUM. SOMEONE SITS BEHIND THE BARS. SINCE 1391. HE CLAIMS TO HAVE TEA."],
      fr: ['A:LA CENDRE DE BRUME ! ↑ ↓ ET SAUT - ET TU ES UNE RUMEUR. RIEN NE TE TOUCHE ET TU PASSES À TRAVERS LES BARREAUX.', "A:DANS LE COLISÉE, UNE PORTE MÈNE AU CACHOT. QUELQU'UN EST DERRIÈRE LES BARREAUX. DEPUIS 1391. IL DIT AVOIR DU THÉ."],
      es: ['A:¡LA CENIZA DE NIEBLA! ↑ ↓ Y SALTO, Y ERES UN RUMOR. NADA TE GOLPEA Y PASAS POR CUALQUIER REJA.', 'A:EN EL COLISEO HAY UNA PUERTA A LA MAZMORRA. ALGUIEN ESTÁ TRAS LOS BARROTES. DESDE 1391. DICE QUE TIENE TÉ.'],
      ja: ['A:霧の灰か！↑↓とジャンプで君はうわさ話になる。何にも当たらず、どんな鉄格子も通り抜ける。', 'A:コロシアムに地下牢への扉がある。鉄格子の向こうに誰かいる。1391年から。お茶があるらしい。'],
      zh: ['A:雾之灰！↑↓加跳跃，你就成了一个传说。什么都打不到你，任何铁栏都能穿过。', 'A:斗技场里有扇通往地牢的门。铁栏后面坐着个人。从1391年起。他说他有茶。'],
    },
