      en: ['NOWHERE        00:00', 'TRANSYLVANIA   23:59', 'HOTEL KRAT  ON FOOT', 'TOMORROW  CANCELLED'],
      fr: ['NULLE PART     00:00', 'TRANSYLVANIE   23:59', 'HÔTEL KRAT   À PIED', 'DEMAIN       ANNULÉ'],
