      ja: ['どこでもない　00:00', 'トランシルヴァニア　23:59', 'ホテル・クラト　徒歩', 'あした　運休'],
      zh: ['不知何处　00:00', '特兰西瓦尼亚　23:59', '克拉特酒店　步行', '明天　停运'],
