    story_howl: {
      de: ['A:DIE SEELE DES WOLFS! ↓ ↘ → UND SPRUNG - UND DU LÄUFST AUF VIER PFOTEN. SCHNELL, FLACH, UND DU BEISST. ↑ MACHT DICH WIEDER ZUM MENSCHEN.', 'A:ÜBRIGENS: IM HOTEL KRAT ÜBER DEM BURGHOF GIBT ES EINE HAUSTIERKLAPPE. DER PORTIER IST SEHR STOLZ DARAUF.'],
      en: ['A:THE WOLF\'S SOUL! ↓ ↘ → AND JUMP - AND YOU RUN ON FOUR PAWS. FAST, LOW, AND YOU BITE. ↑ TURNS YOU HUMAN AGAIN.', 'A:BY THE WAY: HOTEL KRAT ABOVE THE COURTYARD HAS A PET FLAP. THE CONCIERGE IS VERY PROUD OF IT.'],
      fr: ['A:L\'ÂME DE LOUP ! ↓ ↘ → ET SAUT - ET TU COURS SUR QUATRE PATTES. RAPIDE, AU RAS DU SOL, ET TU MORDS. ↑ TE REND HUMAIN.', 'A:AU FAIT : L\'HÔTEL KRAT, AU-DESSUS DE LA COUR, A UNE CHATIÈRE. LE CONCIERGE EN EST TRÈS FIER.'],
      es: ['A:¡EL ALMA DE LOBO! ↓ ↘ → Y SALTO, Y CORRES A CUATRO PATAS. RÁPIDO, A RAS DE SUELO, Y MUERDES. ↑ TE VUELVE HUMANO.', 'A:POR CIERTO: EL HOTEL KRAT, SOBRE EL PATIO, TIENE UNA GATERA. EL CONSERJE ESTÁ MUY ORGULLOSO.'],
      ja: ['A:狼の魂か！↓↘→とジャンプで四つ足になる。速く、低く、噛みつける。↑で人間に戻る。', 'A:ところで、中庭の上のホテル・クラトにはペット用の扉がある。ポーターの自慢らしい。'],
      zh: ['A:狼之魂！↓↘→加跳跃，你就用四条腿跑。又快又低，还会咬。↑变回人形。', 'A:对了：庭院上方的克拉特酒店有扇宠物门。门房很为它骄傲。'],
    },
    story_conc1: {
      de: ['C:WILLKOMMEN IM HOTEL KRAT! DAS EINZIGE HOTEL IN EINEM VAMPIRSCHLOSS. UND DAS BESTE.', 'C:~WIR HABEN FÜNF STERNE.', 'H:IHRE NASE ... WÄCHST.', 'C:BERUFSKRANKHEIT. ICH BIN EINE PUPPE. ICH KANN NICHT LÜGEN. ALSO, ICH KANN SCHON. ES SIEHT NUR JEDER.', 'C:WIR HABEN EINEN STERN. ER STECKT IN DER LAMPE DORT. EIN PAAR MINUTEN DAVOR, UND SIE SIND WIE NEU.', 'C:DER AUFZUG FÄHRT IN JEDEN FLÜGEL. DAS GRAMMOPHON SPIELT JEDE PLATTE, DIE SIE FINDEN.', 'C:~UND DAS FRÜHSTÜCK IST INKLUSIVE.', 'C:... ES GIBT KEIN FRÜHSTÜCK. DER GRAF FRÜHSTÜCKT DIE GÄSTE. MÖCHTEN SIE TROTZDEM EINCHECKEN?'],
      en: ['C:WELCOME TO HOTEL KRAT! THE ONLY HOTEL IN A VAMPIRE CASTLE. AND THE BEST.', 'C:~WE HAVE FIVE STARS.', 'H:YOUR NOSE ... IS GROWING.', 'C:AN OCCUPATIONAL HAZARD. I AM A PUPPET. I CANNOT LIE. WELL, I CAN. EVERYONE JUST SEES IT.', 'C:WE HAVE ONE STAR. IT IS IN THAT LAMP. A FEW MINUTES IN FRONT OF IT AND YOU ARE GOOD AS NEW.', 'C:THE LIFT GOES TO EVERY WING. THE GRAMOPHONE PLAYS ANY RECORD YOU FIND.', 'C:~AND BREAKFAST IS INCLUDED.', 'C:... THERE IS NO BREAKFAST. THE COUNT HAS THE GUESTS FOR BREAKFAST. WOULD YOU STILL LIKE TO CHECK IN?'],
      fr: ['C:BIENVENUE À L\'HÔTEL KRAT ! LE SEUL HÔTEL DANS UN CHÂTEAU DE VAMPIRE. ET LE MEILLEUR.', 'C:~NOUS AVONS CINQ ÉTOILES.', 'H:VOTRE NEZ ... IL POUSSE.', 'C:RISQUE DU MÉTIER. JE SUIS UNE MARIONNETTE. JE NE PEUX PAS MENTIR. ENFIN, SI. ÇA SE VOIT, C\'EST TOUT.', 'C:NOUS AVONS UNE ÉTOILE. ELLE EST DANS CETTE LAMPE. QUELQUES MINUTES DEVANT ET VOUS ÊTES COMME NEUF.', 'C:L\'ASCENSEUR DESSERT CHAQUE AILE. LE GRAMOPHONE JOUE TOUS LES DISQUES QUE VOUS TROUVEZ.', 'C:~ET LE PETIT-DÉJEUNER EST COMPRIS.', 'C:... IL N\'Y A PAS DE PETIT-DÉJEUNER. LE COMTE PREND LES CLIENTS AU PETIT-DÉJEUNER. VOUS VOULEZ TOUJOURS UNE CHAMBRE ?'],
      es: ['C:¡BIENVENIDO AL HOTEL KRAT! EL ÚNICO HOTEL EN UN CASTILLO DE VAMPIROS. Y EL MEJOR.', 'C:~TENEMOS CINCO ESTRELLAS.', 'H:SU NARIZ ... ESTÁ CRECIENDO.', 'C:GAJES DEL OFICIO. SOY UNA MARIONETA. NO PUEDO MENTIR. BUENO, SÍ PUEDO. SOLO QUE SE NOTA.', 'C:TENEMOS UNA ESTRELLA. ESTÁ EN ESA LÁMPARA. UNOS MINUTOS DELANTE Y QUEDA COMO NUEVO.', 'C:EL ASCENSOR VA A TODAS LAS ALAS. EL GRAMÓFONO TOCA CUALQUIER DISCO QUE ENCUENTRE.', 'C:~Y EL DESAYUNO ESTÁ INCLUIDO.', 'C:... NO HAY DESAYUNO. EL CONDE DESAYUNA A LOS HUÉSPEDES. ¿AÚN DESEA REGISTRARSE?'],
      ja: ['C:ホテル・クラトへようこそ！吸血鬼の城にある唯一のホテル。そして最高のホテルです。', 'C:~当ホテルは五つ星です。', 'H:あなたの鼻……伸びてる。', 'C:職業病です。私は人形なので嘘がつけません。いえ、つけますが、皆にばれるのです。', 'C:星はひとつございます。あのランプの中に。前で少し休めば元通りです。', 'C:エレベーターはどの翼にも参ります。蓄音機は見つけたレコードを何でもかけます。', 'C:~朝食は込みです。', 'C:……朝食はございません。伯爵が客を朝食になさいます。それでもチェックインなさいますか？'],
      zh: ['C:欢迎光临克拉特酒店！吸血鬼城堡里唯一的酒店。也是最好的。', 'C:~我们是五星级。', 'H:你的鼻子……在变长。', 'C:职业病。我是木偶，不会说谎。呃，会的。只是大家都看得出来。', 'C:我们有一颗星。就在那盏灯里。在它前面待几分钟，您就焕然一新。', 'C:电梯通往每一侧楼。留声机能放您找到的任何唱片。', 'C:~而且含早餐。', 'C:……没有早餐。伯爵拿客人当早餐。您还要入住吗？'],
    },
    story_conc2: {
      de: ['C:OH! EIN HUND! ... VERZEIHUNG. EIN WOLF. HAUSTIERE SIND BEI UNS SELBSTVERSTÄNDLICH WILLKOMMEN.', 'C:~MENSCHEN ÜBRIGENS AUCH.', 'C:UNTER DER GALERIE, HINTER DER HAUSTIERKLAPPE, IST DER GEPÄCKRAUM. EIN GAST HAT DORT ETWAS VERGESSEN. VOR 200 JAHREN.', 'H:UND WENN ER ZURÜCKKOMMT?', 'C:~DAS WIRD ER BESTIMMT.'],
      en: ['C:OH! A DOG! ... I BEG YOUR PARDON. A WOLF. PETS ARE OF COURSE WELCOME HERE.', 'C:~SO ARE HUMANS, BY THE WAY.', 'C:UNDER THE GALLERY, BEHIND THE PET FLAP, IS THE LUGGAGE ROOM. A GUEST FORGOT SOMETHING THERE. 200 YEARS AGO.', 'H:AND IF HE COMES BACK?', 'C:~I AM SURE HE WILL.'],
      fr: ['C:OH ! UN CHIEN ! ... PARDON. UN LOUP. LES ANIMAUX SONT BIEN SÛR LES BIENVENUS.', 'C:~LES HUMAINS AUSSI, REMARQUEZ.', 'C:SOUS LA GALERIE, DERRIÈRE LA CHATIÈRE, IL Y A LA BAGAGERIE. UN CLIENT Y A OUBLIÉ QUELQUE CHOSE. IL Y A 200 ANS.', 'H:ET S\'IL REVIENT ?', 'C:~J\'EN SUIS CERTAIN.'],
      es: ['C:¡OH! ¡UN PERRO! ... PERDÓN. UN LOBO. LAS MASCOTAS SON BIENVENIDAS, POR SUPUESTO.', 'C:~LOS HUMANOS TAMBIÉN, POR CIERTO.', 'C:BAJO LA GALERÍA, TRAS LA GATERA, ESTÁ LA CONSIGNA. UN HUÉSPED OLVIDÓ ALGO ALLÍ. HACE 200 AÑOS.', 'H:¿Y SI VUELVE?', 'C:~SEGURO QUE VUELVE.'],
      ja: ['C:おや！犬！……失礼、狼でしたか。ペットはもちろん歓迎です。', 'C:~人間も歓迎ですよ、ちなみに。', 'C:回廊の下、ペット用の扉の奥が荷物室です。お客様の忘れ物がございます。二百年前の。', 'H:その人が戻ってきたら？', 'C:~きっと戻られますとも。'],
      zh: ['C:哦！一只狗！……抱歉，是狼。我们当然欢迎宠物。', 'C:~顺便说一句，也欢迎人类。', 'C:回廊下面、宠物门后面是行李房。有位客人在那儿落下了东西。两百年前。', 'H:要是他回来呢？', 'C:~他肯定会回来的。'],
    },
