    relic_boots: { de: 'DAMPFSTIEFEL', en: 'STEAM BOOTS', fr: 'BOTTES À VAPEUR', es: 'BOTAS DE VAPOR', ja: '蒸気ブーツ', zh: '蒸汽靴' },
    relicD_boots: { de: 'SUPERSPRUNG (↑ + DASH)', en: 'SUPER JUMP (↑ + DASH)', fr: 'SUPER SAUT (↑ + DASH)', es: 'SUPERSALTO (↑ + DASH)', ja: 'スーパージャンプ（↑+ダッシュ）', zh: '超级跳跃（↑+冲刺）' },
